-- Journeys build plan J5 — step 2a, scope proposals. Generated by `prisma
-- migrate diff` from the applied lane database, then hand-extended with the two
-- CHECKs Prisma cannot express. Nothing existing changes: no backfill, no
-- alteration of an existing table, so no production data can be affected.
--
-- Every CHECK is exercised by a direct insert in `j5.test.ts`.

-- CreateEnum
CREATE TYPE "ScopeProposalKind" AS ENUM ('ADD', 'REMOVE', 'RESTORE');

-- CreateEnum
CREATE TYPE "ScopeProposalDecision" AS ENUM ('ACCEPTED', 'DECLINED');

-- CreateTable
CREATE TABLE "ScopeProposal" (
    "id" TEXT NOT NULL,
    "contractId" TEXT NOT NULL,
    "kind" "ScopeProposalKind" NOT NULL,
    "scopeItemId" TEXT,
    "requestedKind" "ScopeKind",
    "text" TEXT NOT NULL,
    "lang" TEXT NOT NULL,
    "proposedById" TEXT NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "decidedAt" TIMESTAMP(3),
    "decidedById" TEXT,
    "decision" "ScopeProposalDecision",
    "declineReason" TEXT,
    "createdItemId" TEXT,

    CONSTRAINT "ScopeProposal_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "ScopeProposal_createdItemId_key" ON "ScopeProposal"("createdItemId");

-- CreateIndex
CREATE INDEX "ScopeProposal_contractId_createdAt_idx" ON "ScopeProposal"("contractId", "createdAt");

-- CreateIndex
CREATE INDEX "ScopeProposal_scopeItemId_idx" ON "ScopeProposal"("scopeItemId");

-- AddForeignKey
ALTER TABLE "ScopeProposal" ADD CONSTRAINT "ScopeProposal_contractId_fkey" FOREIGN KEY ("contractId") REFERENCES "Contract"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "ScopeProposal" ADD CONSTRAINT "ScopeProposal_scopeItemId_fkey" FOREIGN KEY ("scopeItemId") REFERENCES "ScopeItem"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "ScopeProposal" ADD CONSTRAINT "ScopeProposal_proposedById_fkey" FOREIGN KEY ("proposedById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "ScopeProposal" ADD CONSTRAINT "ScopeProposal_decidedById_fkey" FOREIGN KEY ("decidedById") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "ScopeProposal" ADD CONSTRAINT "ScopeProposal_createdItemId_fkey" FOREIGN KEY ("createdItemId") REFERENCES "ScopeItem"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- Hand-written (1): a decline *says why* — the customer reads the reason, and a
-- proposal declined with nothing to read is the silence this step exists to
-- remove. Stronger than `IS NOT NULL`, as S2's `FeedbackComment_declined_has_
-- reason` is: a reason of only whitespace is not one. An undecided proposal has
-- a NULL `decision`, `NULL <> 'DECLINED'` is NULL, and a CHECK that evaluates to
-- NULL passes — which is exactly right here, since nothing has been declined.
ALTER TABLE "ScopeProposal" ADD CONSTRAINT "ScopeProposal_declined_has_reason" CHECK (
  "decision" <> 'DECLINED' OR ("declineReason" IS NOT NULL AND btrim("declineReason") <> '')
);

-- Hand-written (2): only an ADD names no item yet. A REMOVE or RESTORE is about
-- a registry row, and one that points at nothing is a proposal no decision could
-- apply. (`kind = 'ADD'` is never NULL, so this cannot pass by evaluating to
-- NULL.)
ALTER TABLE "ScopeProposal" ADD CONSTRAINT "ScopeProposal_target_required" CHECK (
  "kind" = 'ADD' OR "scopeItemId" IS NOT NULL
);
